from collections import Counter
from pathlib import Path
import hashlib, json, re
root = Path.cwd()
ir_path = root / 'build/benchmarks/cpu.ll'
ir = ir_path.read_text()
blocks = {int(n): text for n, text in re.findall(r'^b(\d+):\n(.*?)(?=^b\d+:|^dispatch:)', ir, re.M|re.S)}
paths = {
 'leaf': [745,744,743,742,741,740,739,716,715],
 'recursive': [745,744,743,742,741,740,739,738,737,736,735,734,733,732,731,730,729,728,727,726,725,724,723,722,721,720,719,718,717]
}
path_counts = {}
for name, path in paths.items():
 counts = Counter(re.search(r'@snail_vm_([a-z_]+)\(', blocks[n])[1] for n in path)
 path_counts[name] = {'blocks': path, 'vm_instructions': len(path), 'instruction_counts': dict(counts), 'rust_abi_service_calls': sum(n * (2 if op in ('call','test','return') else 3) for op,n in counts.items()), 'eager_error_string_constructions': counts['constant'] + counts['refer_global']}
def fib(n):
 a,b = 0,1
 for _ in range(n): a,b=b,a+b
 return a
rows=[]
for n in [22,23,24,25]:
 leaves = fib(n+1)
 internal = leaves-1
 calls = leaves+internal
 rows.append({'n':n, 'leaves':leaves, 'internal':internal, 'fib_invocations':calls, 'argument_vectors':2*calls+3*internal, 'local_vectors':calls, 'eager_error_strings':2*leaves+9*internal, 'vm_instruction_entries':9*leaves+29*internal, 'rust_abi_service_calls':24*leaves+80*internal})
totals = {k: sum(r[k] for r in rows)*16 for k in rows[0] if k!='n'}
totals['source_level_allocation_requests'] = totals['argument_vectors']+totals['local_vectors']+totals['eager_error_strings']
print(json.dumps({"paths":path_counts,"per_input":rows,"totals":totals},indent=2))
